function enumValue<T extends string>(values: readonly T[], value: number): T {
  return values[value] ?? values[0];
}

function numeric(value: unknown): number {
  return typeof value === "number" ? value : Number.NaN;
}

function valueIndex<T extends string>(values: readonly T[], value: T): number {
  return values.indexOf(value);
}

function environmentParameterValue(parameter: EnvironmentParameter): number {
  switch (parameter) {
    case EnvironmentParameter.temperature: return 0;
    case EnvironmentParameter.humidity: return 1;
    case EnvironmentParameter.co2: return 2;
    case EnvironmentParameter.pm25: return 3;
    case EnvironmentParameter.pm10: return 4;
    case EnvironmentParameter.formaldehyde: return 5;
    case EnvironmentParameter.tvoc: return 6;
    case EnvironmentParameter.noise: return 7;
    case EnvironmentParameter.illuminance: return 8;
    default: return -1;
  }
}

function pmStandardValue(standard: PMStandard): number {
  switch (standard) {
    case PMStandard.eeaAQI2024: return 0;
    case PMStandard.hj6332026: return 1;
    case PMStandard.epaAQI2026: return 2;
    default: return -1;
  }
}

function formaldehydeStandardValue(standard: FormaldehydeStandard): number {
  switch (standard) {
    case FormaldehydeStandard.who2010: return 0;
    case FormaldehydeStandard.gbt188832022: return 1;
    case FormaldehydeStandard.oehha2008: return 2;
    default: return -1;
  }
}

function humidityStandardValue(standard: HumidityStandard): number {
  switch (standard) {
    case HumidityStandard.epa: return 0;
    case HumidityStandard.uba: return 1;
    default: return -1;
  }
}

function noiseSceneValue(scene: NoiseScene): number {
  switch (scene) {
    case NoiseScene.home: return 0;
    case NoiseScene.sleep: return 1;
    default: return -1;
  }
}

function createAirApi(native: NativeModule): AirRatingApi {
  return Object.freeze({
    co2: (ppm: number) =>
      enumValue(airQualityValues, native._air_rate_co2(numeric(ppm))),
    pm25: (concentration: number, standard = PMStandard.eeaAQI2024) =>
      enumValue(
        airQualityValues,
        native._air_rate_pm25(pmStandardValue(standard), numeric(concentration))
      ),
    pm10: (concentration: number, standard = PMStandard.eeaAQI2024) =>
      enumValue(
        airQualityValues,
        native._air_rate_pm10(pmStandardValue(standard), numeric(concentration))
      ),
    formaldehyde: (
      concentration: number,
      standard = FormaldehydeStandard.who2010
    ) => enumValue(
      airQualityValues,
      native._air_rate_hcho(
        formaldehydeStandardValue(standard),
        numeric(concentration)
      )
    ),
    overall: (input: AirOverallInput = {}) => {
      const pmStandard = input.pmStandard ?? PMStandard.eeaAQI2024;
      const formaldehydeStandard = input.formaldehydeStandard
        ?? FormaldehydeStandard.who2010;
      let mask = 0;
      if (input.co2 != null) mask |= 0x01;
      if (input.pm25 != null) mask |= 0x02;
      if (input.pm10 != null) mask |= 0x04;
      if (input.formaldehyde != null) mask |= 0x08;
      return enumValue(
        airQualityValues,
        native._air_rate_all(
          pmStandardValue(pmStandard),
          formaldehydeStandardValue(formaldehydeStandard),
          numeric(input.co2 ?? 0),
          numeric(input.pm25 ?? 0),
          numeric(input.pm10 ?? 0),
          numeric(input.formaldehyde ?? 0),
          mask
        )
      );
    },
    co2Level: (ppm: number) =>
      enumValue(concentrationLevelValues, native._air_level_co2(numeric(ppm))),
    pm25Level: (concentration: number, standard = PMStandard.eeaAQI2024) =>
      enumValue(
        concentrationLevelValues,
        native._air_level_pm25(pmStandardValue(standard), numeric(concentration))
      ),
    pm10Level: (concentration: number, standard = PMStandard.eeaAQI2024) =>
      enumValue(
        concentrationLevelValues,
        native._air_level_pm10(pmStandardValue(standard), numeric(concentration))
      ),
    formaldehydeLevel: (
      concentration: number,
      standard = FormaldehydeStandard.who2010
    ) => enumValue(
      concentrationLevelValues,
      native._air_level_hcho(
        formaldehydeStandardValue(standard),
        numeric(concentration)
      )
    )
  });
}

function createThermalApi(native: NativeModule): ThermalComfortApi {
  return Object.freeze({
    evaluate: (input: ThermalInput) => {
      const pmv = native._thermal_pmv(
        numeric(input?.temperature),
        numeric(input?.humidity),
        numeric(input?.radiantTemperature),
        numeric(input?.airSpeed),
        numeric(input?.met ?? 1.1),
        numeric(input?.clo ?? 0.7)
      );
      if (!Number.isFinite(pmv)) return null;
      const ppd = native._thermal_ppd(pmv);
      if (!Number.isFinite(ppd)) return null;
      return Object.freeze({
        pmv,
        ppd,
        sensation: enumValue(thermalSensationValues, native._thermal_rate(pmv))
      });
    },
    rateHumidity: (humidity: number, standard = HumidityStandard.uba) =>
      enumValue(
        humidityRatingValues,
        native._thermal_rate_humidity(
          humidityStandardValue(standard),
          numeric(humidity)
        )
      )
  });
}

function createSoundLightApi(native: NativeModule): SoundLightRatingApi {
  return Object.freeze({
    noise: (decibels: number, scene: NoiseScene) =>
      enumValue(
        noiseRatingValues,
        native._noise_rate(noiseSceneValue(scene), numeric(decibels))
      ),
    illuminance: (lux: number) =>
      enumValue(
        illuminanceRatingValues,
        native._illuminance_rate(numeric(lux))
      )
  });
}

function cssColor(rawValue: number): string | null {
  const value = rawValue >>> 0;
  if (value === 0xFFFFFFFF) return null;
  return `#${value.toString(16).toUpperCase().padStart(6, "0")}`;
}

function parameterColors(
  lookup: (role: number) => number
): ParameterColors | null {
  const primary = cssColor(lookup(0));
  const background = cssColor(lookup(1));
  if (primary == null || background == null) return null;
  return Object.freeze({ primary, background });
}

function stateColors(lookup: (role: number) => number): StateColors | null {
  const primary = cssColor(lookup(0));
  const background = cssColor(lookup(1));
  const graphic = cssColor(lookup(2));
  const text = cssColor(lookup(3));
  if (primary == null || background == null || graphic == null || text == null) {
    return null;
  }
  return Object.freeze({ primary, background, graphic, text });
}

function createColorsApi(native: NativeModule): EnvironmentColorsApi {
  return Object.freeze({
    parameter: (parameter: EnvironmentParameter) => {
      const parameterValue = environmentParameterValue(parameter);
      return parameterColors(
        (role) => native._env_color_parameter(parameterValue, role)
      );
    },
    air: (parameter: AirColorParameter, quality: AirQuality) => {
      const parameterValue = environmentParameterValue(parameter);
      const qualityValue = valueIndex(airQualityValues, quality);
      return stateColors(
        (role) => native._env_color_air(parameterValue, qualityValue, role)
      );
    },
    thermal: (sensation: ThermalSensation) => {
      const value = valueIndex(thermalSensationValues, sensation);
      return stateColors((role) => native._env_color_thermal(value, role));
    },
    humidity: (rating: HumidityRating) => {
      const value = valueIndex(humidityRatingValues, rating);
      return stateColors((role) => native._env_color_humidity(value, role));
    },
    noise: (rating: NoiseRating) => {
      const value = valueIndex(noiseRatingValues, rating);
      return stateColors((role) => native._env_color_noise(value, role));
    },
    illuminance: (rating: IlluminanceRating) => {
      const value = valueIndex(illuminanceRatingValues, rating);
      return stateColors((role) => native._env_color_illuminance(value, role));
    }
  });
}

/** Initialize the Wasm module once, then reuse the returned stateless API. */
export async function createEnvironmentRating(
  options: CreateEnvironmentRatingOptions = {}
): Promise<EnvironmentRating> {
  const nativeOptions: NativeOptions = {};
  if (options.wasmUrl != null) {
    const wasmUrl = String(options.wasmUrl);
    nativeOptions.locateFile = (path, prefix) =>
      path.endsWith(".wasm") ? wasmUrl : `${prefix}${path}`;
  }
  if (options.wasmBinary != null) {
    nativeOptions.wasmBinary = options.wasmBinary instanceof Uint8Array
      ? options.wasmBinary
      : new Uint8Array(options.wasmBinary);
  }

  const native = await (createNativeModule as NativeFactory)(nativeOptions);
  return Object.freeze({
    air: createAirApi(native),
    thermal: createThermalApi(native),
    soundLight: createSoundLightApi(native),
    colors: createColorsApi(native)
  });
}
